$alts=q_alternativas($q);$nonEmpty=array_values(array_filter($alts,static fn($a)=>trim((string)$a)!==''));$gab=(int)$q['gabarito'];$gradable=$gab>=0&&$gab<=4&&count($nonEmpty)>=2;$answerable=count($nonEmpty)>=2;
$ultima=null;$fav=false;if($uid){$m=user_answers_map($uid,[(int)$q['id']]);$ultima=$m[(int)$q['id']]??null;$st=$pdo->prepare('SELECT 1 FROM favoritos WHERE user_id=? AND questao_id=?');$st->execute([$uid,$q['id']]);$fav=(bool)$st->fetchColumn();}
$st=$pdo->prepare('SELECT COUNT(*) t,COALESCE(SUM(correta),0) c FROM respostas WHERE questao_id=? AND avaliavel=1');$st->execute([$q['id']]);$qs=$st->fetch();
$st=$pdo->prepare('SELECT c.*,u.nome FROM comentarios c JOIN users u ON u.id=c.user_id WHERE c.questao_id=? AND c.aprovado=1 ORDER BY c.id DESC LIMIT 30');$st->execute([$q['id']]);$comments=$st->fetchAll();

